  "code": "def generated_loss(batch, model_output, extra):\n    advantage_w = batch['advantage_w']\n    advantage_l = batch['advantage_l']\n    cost_gap = batch['cost_gap']\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    weight = batch['weight']\n\n    sign_cost_gap = ops.tanh(cost_gap / (ops.abs(cost_gap) + 1e-8))  # approximate sign\n    pref_signal_w = advantage_w * sign_cost_gap\n    pref_signal_l = advantage_l * sign_cost_gap\n    loss_terms = ops.logsigmoid(pref_signal_w) + ops.logsigmoid(pref_signal_l)\n    loss = -ops.mean(loss_terms * weight)\n    return loss"
}

