{
  "name": "pairwise_advantage_tanh_loss",
  "intuition": "This loss computes the difference between advantages for w and l and applies a tanh transformation on their product with the log probability difference. The tanh function bounds the gradient and encourages a margin between better and worse options, stabilizing training especially when advantage signals are noisy or scale-sensitive.",
  "pseudocode": "adv_gap = advantage_w - advantage_l\nscore_diff = log_prob_w - log_prob_l\nscaled = tanh(beta * adv_gap * score_diff)\nloss = mean(weight * (1 - scaled))",
  "hyperparams": {
    "paradigm_family": "pairwise_ranking",
    "signal_family": "advantage_gap",
    "link_family": "tanh",
    "agg_family": "mean",
    "constraint_family": "none"
  },
  "operators_used": ["tanh", "mul", "sub", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', ops.ones_like(lpw))\n    adv_w = batch['advantage_w']\n    adv_l = batch['advantage_l']\n    beta = float(extra.get('beta', extra.get('hyperparams', {}).get('beta', 1.5)))\n    adv_gap = ops.sub(adv_w, adv_l)\n    score_diff = ops.sub(lpw, lpl)\n    scaled = ops.tanh(ops.mul(beta, ops.mul(adv_gap, score_diff)))\n    loss_per_pair = ops.mul(weight, ops.sub(ops.ones_like(scaled), scaled))\n    return ops.mean(loss_per_pair)"
}

